function esNovo(){openModal(`${mh('Cadastrar cliente')}<div class="mb"><div class="formgrid"><div class="field"><label>CNPJ <span class="req">*</span> ${info('Busca no Clínicas; se não achar, numa base pública da Receita; se falhar, preenchimento manual.')}</label><input class="in" placeholder="00.000.000/0000-00" onblur="toast('CNPJ encontrado na Receita: razão social e endereço preenchidos')"></div><div class="field"><label>Razão social <span class="req">*</span></label><input class="in"></div><div class="field"><label>Nome fantasia <span class="req">*</span></label><input class="in"></div><div class="field"><label>CEP <span class="req">*</span></label><input class="in" placeholder="preenche o endereço"></div><div class="field"><label>Responsável · nome, CPF, cargo, contato, e-mail <span class="req">*</span> ${info('Vira o primeiro administrador; a senha é dele, criada pelo link de e-mail.')}</label><input class="in"></div><div class="field"><label>Enquadramento</label><select class="in"><option>Clínica com laboratório e imagem (rede de unidades)</option><option>Laboratório central (rede de postos)</option><option>Clínica independente</option><option>Independente</option><option>Posto de coleta</option><option>Hospitalar</option><option>Veterinário</option></select></div><div class="field"><label>Plano <span class="req">*</span></label><select class="in"><option>Essencial</option><option>Rede</option><option>Hospitalar</option></select></div><div class="field"><label>Pagamento</label><select class="in"><option>Cartão</option><option>Boleto</option><option>Fora do sistema</option></select></div></div><label class="check"><input type="checkbox">Li e aceito os Termos de Uso e o Contrato (DeoClinic como operador dos dados, suboperadores listados)</label></div><div class="mf"><button class="btn ghost" onclick="closeModal()">Cancelar</button><button class="btn" onclick="closeModal();retorno('ok','Cliente cadastrado','Link de definição de senha enviado ao responsável. O passo a passo de implantação mostra o que falta para o primeiro laudo.')">Cadastrar</button></div>`)}
function esImplant(i){const e=ESTAB[i===undefined?2:i];const passos=[['Logo e dados para o laudo (CNES, RT e substitutos, licença)',e.impl>=20],['Unidades e chaves (atende, coleta, processa, fatura)',e.impl>=40],['Assistente de implantação (configurações opcionais, com o i)',e.impl>=60],['Exames, bancadas e tabelas de preço',e.impl>=80],['Importação do sistema antigo',e.impl>=100],['Primeiro laudo de teste',e.impl>=100]];
 openDrawer('Implantação · '+esc(e.n),`<p style="font-size:14px;color:var(--fg2)">${e.impl}% feito. O passo a passo mostra o que já foi feito e avisa o que falta para o primeiro laudo.</p><div class="steps">${passos.map(([p,ok],j)=>`<div class="stp ${ok?'ok':(j&&passos[j-1][1])?'cur':''}"><span class="dot2"></span><div class="st">${p}<small>${ok?'feito':'pendente'}</small></div></div>`).join('')}</div><div class="row"><button class="btn" onclick="closeDrawer();location.hash='#config'">Abrir o assistente</button><button class="btn ghost" onclick="toast('Tour do primeiro acesso reaberto')">Rever o tour</button></div>`)}
