let CF_PASSO=0;
const CF_ASSIST=[['Como a recepção chama o paciente para a coleta?','Pelo nome em voz alta (padrão) ou por senha num painel. O painel ajuda em unidades grandes; o nome é mais simples em postos pequenos.',['Pelo nome','Por senha no painel']],['Quais canais avisam o paciente do resultado?','WhatsApp e e-mail ligados, SMS desligado. Mensagens nunca trazem resultado; vai link com senha.',['WhatsApp e e-mail','Só WhatsApp','WhatsApp, e-mail e SMS']],['Esta unidade faz coleta domiciliar?','Liga a agenda por janelas, a rota, o kit e o app do coletador.',['Não','Sim, com impressora portátil','Sim, com etiquetas pré-impressas']],['O controle de qualidade reprovado bloqueia a liberação?','Padrão: bloqueia até repetir e aprovar; o Dr. pode liberar com justificativa. Desligar mostra o aviso da RDC 978/2025.',['Bloqueia (padrão)','Só avisa']],['Vai usar a gestão da qualidade (NCs, equipamentos, documentos)?','Opcional. Desligada, as ocorrências continuam registradas e os indicadores no dashboard.',['Sim','Agora não']],['Atende pets?','Liga referências e críticos por espécie, laudo com tutor e CRMV.',['Não','Sim']]];
function cfAssistente(){CF_PASSO=0;cfPasso()}
function cfPasso(){const [p,i,ops]=CF_ASSIST[CF_PASSO];openModal(`${mh('Assistente de implantação · '+(CF_PASSO+1)+' de '+CF_ASSIST.length)}<div class="mb"><div class="at-steps">${CF_ASSIST.map((_,j)=>`<span class="at-step ${j===CF_PASSO?'cur':j<CF_PASSO?'done':''}"><b>${j+1}</b></span>`).join('')}</div><h4 style="margin-top:12px">${p} ${info(i)}</h4><p style="font-size:14px;color:var(--fg2)">${i}</p><div class="row">${ops.map((o,j)=>`<label class="chip ${j===0?'on':''}"><input type="radio" name="cfa" hidden ${j===0?'checked':''}>${o}</label>`).join('')}</div></div><div class="mf"><button class="btn ghost" onclick="closeModal()">Pular, volto depois</button>${CF_PASSO?`<button class="btn sec" onclick="CF_PASSO--;cfPasso()">Voltar</button>`:''}<button class="btn" onclick="${CF_PASSO<CF_ASSIST.length-1?'CF_PASSO++;cfPasso()':"closeModal();retorno('ok','Implantação configurada','Tudo pode ser mudado em Configurações; cada mudança fica registrada. O assistente pode rodar de novo.')"}">${CF_PASSO<CF_ASSIST.length-1?'Próxima':'Concluir'}</button></div>`)}
