function inDetalhe(i){const x=IN_PARC[i];const adm=PERFIL==='admin';const campo=(l,v,tip)=>adm?`<div class="field"><label>${l}${tip?' '+info(tip):''}</label><input class="in" value="${esc(v)}"></div>`:`<div class="field"><label>${l}</label><div style="font-size:14px">${esc(v)}</div></div>`;
 openDrawer(x.p,`${adm?'':'<div class="alert info"><span>Só leitura: só o Administrador altera integrações.</span></div>'}${kvs([['Tipo',x.t],['Padrão',x.pa],['Situação',`<span class="badge ${x.s==='Ativo'?'ok':x.s==='Com falha'?'err':x.s==='Em testes'?'info':'neutral'}">${x.s}</span>`],['Chamadas (24 h)',x.n+(x.f!=='0'&&x.f!=='—'?' · <span class="prazo-err">'+x.f+' falhas</span>':'')],['Eventos',x.ev]])}<h4 style="margin-top:10px">Configuração ${info('Chave mostrada uma vez; credenciais cifradas; toda mudança vai para a auditoria com antes e depois.')}</h4><div class="formgrid">${campo('Endereço de callback',x.c)}${campo('Permissões por recurso',x.perm)}${campo('Limite de chamadas',x.lim)}${campo('Versão da API','v1')}</div>${x.t.startsWith('App')?'<div class="alert info"><span><b>Um app para os dois perfis:</b> coletador e Dr. entram no mesmo aplicativo; o perfil do usuário decide a área que abre. Sem um segundo app para manter.</span></div>':''}<div class="row" style="margin-top:12px;gap:6px">${adm?`<button class="btn" onclick="toast('Integração salva; antes e depois na auditoria')">Salvar</button><button class="btn sec" onclick="toast('Chave rotacionada; a antiga vale por 24 h')">Nova chave</button><button class="btn ghost" onclick="toast('Ambiente simulado: mensagem de teste enviada e recebida')">Testar</button><button class="btn ghost" onclick="modalOk('Desligar integração?','<p>Mensagens param de sair e de entrar; a fila guarda as pendentes.</p>','Desligar','toast(\'Integração desligada; registrado\',\'warn\')','danger')">Desligar</button>`:''}<button class="btn ghost" onclick="closeDrawer();IN_ABA='monitor';reView()">Ver mensagens</button></div>`)}
function inNovo(){openModal(`${mh('Cadastrar parceiro')}<div class="mb"><div class="formgrid"><div class="field"><label>Parceiro <span class="req">*</span></label><input class="in"></div><div class="field"><label>Tipo</label><select class="in"><option>Clínicas</option><option>Apoio</option><option>Hospital</option><option>Laboratório apoiado (DeoClinic como apoio)</option><option>RNDS</option></select></div><div class="field"><label>Endereço de callback ${info('Onde o DeoClinic avisa cada evento na hora (coleta, recebimento, laudo, retificação, recoleta, crítico).')}</label><input class="in" placeholder="https://"></div><div class="field"><label>Versão da API</label><select class="in"><option>v1</option></select></div><div class="field"><label>Limite de chamadas</label><input class="in" value="600 por minuto"></div><div class="field"><label>Permissões por recurso</label><input class="in" value="pedido, paciente, amostra, resultado"></div></div><p class="tl">A chave é mostrada uma vez e nunca mais; credenciais ficam cifradas.</p></div><div class="mf"><button class="btn ghost" onclick="closeModal()">Cancelar</button><button class="btn" onclick="closeModal();retorno('ok','Parceiro cadastrado','Chave gerada e copiada. Teste com o ambiente simulado antes de ligar em produção.')">Cadastrar e gerar chave</button></div>`)}
