/* ---------- Dr. Deo pequeno com fala por setor (anotação 125): deoFala(nº da brincadeira, {perfil: frase, todos: frase}) ---------- */
function deoFala(n,m){if(!BRINCA)return '';const t=m[PERFIL]||m.todos;if(!t)return '';return `<div class="deo">${FIG('ok','pq')}<div class="fala"><b>Dr. Deo diz:</b> ${t}<span class="fun">brincadeira ${n}</span></div></div>`}

/* ======================= 108. Teste de comunicação do aparelho ======================= */
function apTestar(nome,conn,proto){const a=APARELHOS.find(x=>x.n===nome)||{};conn=conn||a.conn||'Rede 192.168.0.50:5100';proto=proto||a.proto||'ASTM E1394';const falha=a.hora==='calado há 1h48'||a.hora==='sem integração';
 const passos=[['Agente local encontrado','computador ligado ao aparelho, chave válida'],['Porta e endereço','abrindo '+esc(conn)],['Handshake '+esc(proto),'ENQ → ACK'],['Mensagem de teste enviada','Q (query) sem tubo, só para ouvir o aparelho'],['Resposta recebida','']];
 openModal(`${mh('Teste de comunicação · '+esc(nome))}<div class="mb"><p class="tl" style="margin-bottom:6px">O DeoClinic pede ao agente local que fale com o aparelho e espera a resposta. Nada é gravado no aparelho nem em pedidos. ${info('Serve para conferir cabo, porta, IP e protocolo antes de ligar a integração de verdade. O resultado fica registrado na auditoria do aparelho.')}</p><div class="ap-passos" id="apPassos">${passos.map((p,i)=>`<div id="apP${i}"><span class="st">${i+1}</span><span>${p[0]}<br><small style="margin:0;white-space:normal">${p[1]}</small></span><small id="apT${i}"></small></div>`).join('')}</div><div id="apRes"></div></div><div class="mf"><button class="btn ghost" onclick="closeModal()">Fechar</button><button class="btn sec" id="apRe" disabled onclick="apTestar('${esc(nome)}')">Testar de novo</button></div>`);
 let t=0;const tempos=[180,260,420,310,falha?3000:140];passos.forEach((p,i)=>{t+=tempos[i];setTimeout(()=>{const el=document.getElementById('apP'+i);if(!el)return;const st=el.querySelector('.st');const erro=falha&&i===4;st.className='st '+(erro?'err':'ok');st.textContent=erro?'!':'✓';document.getElementById('apT'+i).textContent=erro?'sem resposta em 3 s':tempos[i]+' ms';if(i<4){const n=document.getElementById('apP'+(i+1));if(n)n.querySelector('.st').className='st run'}
  if(i===4){const r=document.getElementById('apRes');const re=document.getElementById('apRe');if(re)re.disabled=false;if(!r)return;r.innerHTML=erro?`<div class="figrow" style="margin-top:6px">${FIG('erro','pq')}<div><b style="color:var(--err)">Sem resposta do aparelho.</b><p class="tl">O agente está no ar e a porta abriu, mas o aparelho não respondeu ao handshake. Confira se o modo HOST está ligado no aparelho, o cabo e a velocidade da porta (9600/8/N/1 no DxH; no AU680, LAN com Direção HOST).</p></div></div>`:`<div class="figrow" style="margin-top:6px">${FIG('ok','pq')}<div><b style="color:var(--ok)">Aparelho respondeu em ${t} ms.</b><p class="tl">Cabo, porta e protocolo conferem. Pode salvar e ligar a integração; o primeiro resultado real aparece em Mensagens.</p></div></div>`}},t)});
 setTimeout(()=>{const n=document.getElementById('apP0');if(n)n.querySelector('.st').className='st run'},30)}
function apNovo(){openModal(`${mh('Cadastrar aparelho')}<div class="mb"><div class="formgrid"><div class="field"><label>Nome <span class="req">*</span></label><input class="in" id="apNome" placeholder="Ex.: AU680"></div><div class="field"><label>Modelo</label><input class="in" placeholder="Ex.: Beckman Coulter AU680"></div><div class="field"><label>Bancada <span class="req">*</span></label><select class="in">${BANCADAS.filter(b=>b.ativo).map(b=>`<option>${b.n}</option>`).join('')}</select></div><div class="field"><label>Perfil de mensagens ${info('Perfil pronto para cada família de aparelho; "AU (Beckman)" é o do AU680, sem middleware (decisão de 29/10).')}</label><select class="in" id="apPerfil"><option>DxH (Beckman) · ASTM E1394</option><option>AU (Beckman) · ASTM, LAN com Direção HOST</option><option>Genérico ASTM E1381/E1394</option><option>Genérico HL7 v2</option></select></div><div class="field"><label>Conexão</label><select class="in" id="apConn" onchange="document.getElementById('apRede').hidden=this.value!=='Rede';document.getElementById('apSerial').hidden=this.value!=='Serial'"><option>Rede</option><option>Serial</option></select></div><div class="field" id="apRede"><label>Endereço e porta ${info('IP do aparelho (ou do computador dele) e a porta configurada no modo HOST.')}</label><input class="in" id="apIp" value="192.168.0.50:5100"></div><div class="field" id="apSerial" hidden><label>Porta serial e velocidade</label><input class="in" value="COM3 · 9600 8N1"></div><div class="field"><label>Onde fica a crítica ${info('Padrão: crítica no DeoClinic (decisão de 29/10). Pode ser nas regras do próprio aparelho, por aparelho.')}</label><select class="in"><option>No DeoClinic (padrão)</option><option>Nas regras do aparelho</option></select></div><div class="field"><label>Simbologia aceita ${info('Conferida ao gerar o código do tubo; aviso antes de imprimir.')}</label><input class="in" value="Code 128"></div><div class="field"><label>Tamanho máximo do ID</label><input class="in" value="16"></div><div class="field"><label>Dígito verificador</label><select class="in"><option>Não</option><option>Sim</option></select></div></div><div class="alert info" style="margin-top:10px"><span><b>Antes de salvar, teste:</b> o botão abaixo pede ao agente local que fale com o aparelho e mostra passo a passo onde parou, se parar.</span></div></div><div class="mf"><button class="btn ghost" onclick="closeModal()">Cancelar</button><button class="btn sec" onclick="apTestar((document.getElementById('apNome').value||'novo aparelho'),document.getElementById('apConn').value==='Rede'?'Rede '+document.getElementById('apIp').value:'Serial COM3',document.getElementById('apPerfil').value.includes('HL7')?'HL7 v2':'ASTM')" ${tipAttr('Testar comunicação','Agente → porta → handshake → mensagem de teste → resposta, com o tempo de cada passo.')}>Testar comunicação</button><button class="btn" onclick="closeModal();retorno('ok','Aparelho cadastrado','Chave do agente gerada. Instale o agente no computador ligado ao aparelho, cole a chave e rode o teste de comunicação na ficha.')">Cadastrar e gerar chave</button></div>`)}
/* Botão de teste na ficha de cada aparelho (quadro do monitoramento) e Dr. Deo na tela */
{const _ap=VIEWS.aparelhos;VIEWS.aparelhos=()=>{let h=_ap();h=h.replace(/<button class="btn sm sec" onclick="toast\('Mensagens brutas de ([^']+) por data'\)">/g,(m,n)=>`<button class="btn sm" onclick="apTestar('${n}')" ${tipAttr('Testar comunicação','Pede ao agente que fale com o aparelho e mostra passo a passo a resposta.')}>Testar comunicação</button>`+m);
 return h}}

/* ======================= 121 a 123. Usuário: ficha completa, foto, permissões e link de cadastro ======================= */
const US_FOTO={};  // quem já tem foto no protótipo: ninguém ainda; Tirar foto / Enviar foto na ficha liga a foto de exemplo (30/10)
const US_EXC={};         // exceções de permissão por usuário: US_EXC[i] = {módulo: true/false}
let US_PERFIL_SEL='';
const SILHUETA='<svg viewBox="0 0 64 64" aria-hidden="true"><circle cx="32" cy="24" r="12" fill="rgba(255,255,255,.92)"/><path d="M10 60c2-14 11-20 22-20s20 6 22 20z" fill="rgba(255,255,255,.92)"/></svg>';
/* avatarHtml(usuário, índice): foto guardada pequena (200 × 200, ~15 KB) ou as iniciais */
function avatarHtml(u,i,cls){const foto=US_FOTO[i];return `<span class="avatar ${foto?'foto':''} ${cls||''}" title="${esc(u.n)}${foto?' · foto':''}">${foto?SILHUETA:u.ini}</span>`}
function usFoto(i,modo){US_FOTO[i]=true;const a=document.getElementById('usAv');if(a)a.outerHTML=avatarHtml(USUARIOS[i]||{n:'',ini:'?'},i,'').replace('class="avatar','id="usAv" class="avatar');toast(modo==='cam'?'Foto tirada pela câmera e guardada em 200 × 200 (≈ 15 KB)':'Foto enviada, recortada e guardada em 200 × 200 (≈ 15 KB)');if(i===0)usTopo()}
function usFotoTirar(i){US_FOTO[i]=false;const a=document.getElementById('usAv');if(a)a.outerHTML=avatarHtml(USUARIOS[i]||{n:'',ini:'?'},i,'').replace('class="avatar','id="usAv" class="avatar');toast('Foto removida');if(i===0)usTopo()}
/* A foto aparece no sistema: no topo (quem está logado) e na lista de usuários */
function usTopo(){const t=document.querySelector('header .actions .avatar');if(!t)return;const u=USUARIOS[0];t.className='avatar'+(US_FOTO[0]?' foto':'');t.innerHTML=US_FOTO[0]?SILHUETA:u.ini;t.title=u.n}
usTopo();
{const _us=VIEWS.usuarios;VIEWS.usuarios=()=>{let h=_us();USUARIOS.forEach((u,i)=>{if(US_FOTO[i])h=h.replace(`<span class="avatar">${u.ini}</span><div class="two">${esc(u.n)}`,`${avatarHtml(u,i)}<div class="two">${esc(u.n)}`)});
 return h}}
const PERM_DESC={};PERM_MOD.forEach(m=>PERM_DESC[m]=permAcoes(m).join(', ')); // 04/11: ações por módulo vêm de PERM_ACOES (telas-cadastros.js)
const usPermOn=(i,perfil,m)=>{const e=US_EXC[i]||{};return m in e?e[m]:(PERM_PERFIL[perfil]||[]).includes(m)};
function usPermLista(i,perfil,ver){const adm=PERFIL==='admin';return `<div class="us-perm" id="usPerm">${PERM_MOD.map(m=>{const on=usPermOn(i,perfil,m),exc=(US_EXC[i]||{})[m]!==undefined;return `<div class="perm ${exc?'exc':''}" ${adm&&!ver?`onclick="usPermEdit(${i===undefined?'undefined':i},'${perfil}','${m.replace(/'/g,"\\'")}')" ${tipAttr(m,'Clique para ligar ou desligar: só para este usuário ou para todos com o perfil '+nomePerfil(perfil)+'.')}`:tipAttr(m,'Só o Administrador altera permissões.')}><div>${m}<small>${PERM_DESC[m]||'ver, incluir, alterar, desativar'}</small></div><label class="switch" onclick="event.stopPropagation()"><input type="checkbox" ${on?'checked':''} disabled><span class="tr"></span></label></div>`}).join('')}</div>`}
function usPerfilSel(i,perfil,ver){US_PERFIL_SEL=perfil;const el=document.getElementById('usPerm');if(el)el.outerHTML=usPermLista(i,perfil,ver);document.querySelectorAll('#modal label.chip[data-perfil]').forEach(c=>c.classList.toggle('on',c.dataset.perfil===perfil))}
/* 122: uma permissão clicada abre a escolha: só este usuário (exceção) ou todos com o perfil (muda o modelo) */
function usPermEdit(i,perfil,m){const on=usPermOn(i,perfil,m);const u=USUARIOS[i]||{n:'novo usuário'};const acoes=(PERM_DESC[m]||'ver, incluir, alterar, desativar').split(', ');
 openModal(`${mh('Permissão · '+esc(m))}<div class="mb"><p class="tl">Hoje: <b>${on?'ligada':'desligada'}</b> para ${esc(u.n)} (perfil ${nomePerfil(perfil)}${(US_EXC[i]||{})[m]!==undefined?', como exceção deste usuário':', pelo perfil'}). ${info('Alterar só este usuário cria uma exceção: o perfil continua igual para os outros. Alterar todos muda o modelo do perfil, e vale na hora para quem não tem exceção.')}</p><div class="switchrow"><div>${esc(m)}<small>ligar ou desligar o módulo inteiro</small></div><label class="switch"><input type="checkbox" id="usPmOn" ${on?'checked':''} onchange="document.querySelectorAll('#usPmAcs input').forEach(c=>c.checked=this.checked)"><span class="tr"></span></label></div><h4 style="margin-top:10px">Ações dentro do módulo ${info('Ligar uma ação liga junto o "ver". Cada ação tem o i com o que libera.')}</h4><div class="row" id="usPmAcs" style="gap:6px 14px">${acoes.map(a=>`<label class="check" style="font-size:14px"><input type="checkbox" ${on?'checked':''}>${a}</label>`).join('')}</div><div class="alert info" style="margin-top:10px"><span><b>${(n=>n+(n===1?' usuário ativo tem':' usuários ativos têm'))(USUARIOS.filter(x=>x.perfil===perfil&&x.sit==='Ativo').length)}</b> o perfil ${nomePerfil(perfil)}. Toda alteração vai para a auditoria com antes e depois.</span></div></div><div class="mf"><button class="btn ghost" onclick="usForm(${i===undefined?'undefined':i})">Cancelar</button><button class="btn sec" onclick="usPermSalva(${i===undefined?'undefined':i},'${perfil}','${m.replace(/'/g,"\\'")}','um')">Alterar só este usuário</button><button class="btn" onclick="usPermSalva(${i===undefined?'undefined':i},'${perfil}','${m.replace(/'/g,"\\'")}','todos')">Alterar todos com este perfil</button></div>`)}
function usPermSalva(i,perfil,m,quem){const v=document.getElementById('usPmOn').checked;if(quem==='um'){(US_EXC[i]=US_EXC[i]||{})[m]=v;toast(`${m}: ${v?'ligada':'desligada'} só para este usuário (exceção)`)}else{const l=PERM_PERFIL[perfil]||(PERM_PERFIL[perfil]=[]);const k=l.indexOf(m);if(v&&k<0)l.push(m);if(!v&&k>=0)l.splice(k,1);if(US_EXC[i])delete US_EXC[i][m];toast(`${m}: ${v?'ligada':'desligada'} para todos do perfil ${nomePerfil(perfil)} (${USUARIOS.filter(x=>x.perfil===perfil).length} usuários)`)}usForm(i);US_PERFIL_SEL=perfil;setTimeout(()=>usPerfilSel(i,perfil),0)}
function usForm(i,ver){const u=USUARIOS[i]||{n:'',email:'',perfil:'recepcao',unids:[10],cons:''};const d=ver?'disabled':'';const perfil=US_PERFIL_SEL&&!ver&&USUARIOS[i]&&US_PERFIL_SEL!==u.perfil?US_PERFIL_SEL:u.perfil;US_PERFIL_SEL='';const novo=i===undefined;const assina=['dr','medico','imagem'].includes(perfil);const adm=PERFIL==='admin';
 const cons=(u.cons||'').match(/^(\S+)\s+(.*?)\s*(\d+)$/)||[];
 openModal(`${mh(novo?'Cadastrar usuário':(ver?esc(u.n):'Editar usuário'))}<div class="mb">
<div class="us-foto">${avatarHtml(u,i,'').replace('class="avatar','id="usAv" class="avatar')}<div><b>Foto ${info('Aparece no topo do sistema, na lista de usuários, na fila da coleta e no chat interno. Guardada pequena (200 × 200, cerca de 15 KB) fora das tabelas de busca: pesquisas usam só nome, CPF e e-mail, que são indexados; a foto nunca pesa uma consulta.')}</b><div class="acts" style="margin-top:4px">${ver?'':`<button class="btn sm sec" onclick="usFoto(${novo?'undefined':i},'cam')">Tirar foto (câmera)</button><button class="btn sm ghost" onclick="usFoto(${novo?'undefined':i},'arq')">Enviar foto</button><button class="btn sm ghost" onclick="usFotoTirar(${novo?'undefined':i})">Remover</button>`}</div><p class="tl" style="margin-top:4px">Pelo celular, a câmera abre direto; o sistema recorta em círculo.</p></div></div>
<h4>Dados básicos</h4><div class="formgrid"><div class="field"><label>Nome completo <span class="req">*</span></label><input class="in" value="${esc(u.n)}" ${d}></div><div class="field"><label>Nome social ${info('Como a pessoa quer ser chamada no sistema e nas senhas; opcional.')}</label><input class="in" value="" ${d}></div><div class="field"><label>CPF <span class="req">*</span> ${info('Único na plataforma (D1): um login por pessoa; ela escolhe a clínica ao entrar.')}</label><input class="in" value="${u.n?'***.***.***-**':''}" ${d} oninput="this.value=mCPF(this.value)"></div><div class="field"><label>Data de nascimento</label><input class="in" type="date" value="${u.n?'1979-09-12':''}" ${d}></div><div class="field"><label>Telefone / WhatsApp <span class="req">*</span></label><input class="in" value="${u.n?'(85) 9****-****':''}" ${d}></div><div class="field"><label>E-mail <span class="req">*</span> ${info('É o login e recebe o e-mail de ativação.')}</label><input class="in" value="${u.email}" ${d}></div></div>
<h4 style="margin-top:12px">Endereço ${info('Opcional; usado em documentos de RH e para a coleta domiciliar quando o coletador sai de casa.')}</h4><div class="formgrid"><div class="field"><label>CEP</label><div class="row" style="gap:6px;flex-wrap:nowrap"><input class="in" id="usCep" value="${u.n?'60150-160':''}" ${d} placeholder="00000-000" style="min-width:0"><button class="btn sm sec" ${d} onclick="usCep()" ${tipAttr('Buscar CEP','Preenche rua, bairro, cidade e UF pelo CEP (ViaCEP).')}>Buscar</button></div></div><div class="field" style="grid-column:span 2"><label>Logradouro</label><input class="in" id="usRua" value="${u.n?'Rua Tibúrcio Cavalcante':''}" ${d}></div><div class="field"><label>Número</label><input class="in" value="${u.n?'1230':''}" ${d}></div><div class="field"><label>Complemento</label><input class="in" value="${u.n?'Sala 402':''}" ${d}></div><div class="field"><label>Bairro</label><input class="in" id="usBairro" value="${u.n?'Aldeota':''}" ${d}></div><div class="field"><label>Cidade</label><input class="in" id="usCidade" value="${u.n?'Fortaleza':''}" ${d}></div><div class="field"><label>UF</label><input class="in" id="usUf" value="${u.n?'CE':''}" ${d} maxlength="2"></div></div>
<h4 style="margin-top:12px">Perfil e permissões ${info('Selecionar o perfil carrega as permissões padrão; clique numa permissão para mudar só neste usuário (exceção) ou em todos com o perfil.')}</h4><div class="row">${PERFIS.map(p=>`<label class="chip ${perfil===p[0]?'on':''}" data-perfil="${p[0]}"><input type="radio" name="usp" hidden ${perfil===p[0]?'checked':''} ${d} onchange="usPerfilSel(${novo?'undefined':i},'${p[0]}',${!!ver})">${p[1]}</label>`).join('')}</div>${usPermLista(i,perfil,ver)}${adm||ver?'':'<p class="tl">Só o Administrador altera permissões.</p>'}
<h4 style="margin-top:12px">Unidades e bancadas</h4><div class="row">${[10,12,14].map(x=>`<label class="check"><input type="checkbox" ${u.unids.includes(x)?'checked':''} ${d}>${unidNome(x).split(' · ')[0]}${x===10?' (padrão)':''}</label>`).join('')}</div><p class="tl">Quem tem mais de uma unidade vê tudo junto; a unidade atual vale só para impressora, caixa e novo atendimento. Bancadas: ${u.banc?u.banc.join(', '):'todas'}.</p>
<h4 style="margin-top:12px">Registro profissional e assinatura ${info('Obrigatórios para quem libera resultados (perfil Dr.); a forma de assinatura (ICP-Brasil em nuvem, certificado A1 ou assinatura avançada) é escolha da clínica.')}</h4>${assina?'':'<p class="tl">Este perfil não assina laudos; preencha só se a pessoa tiver registro.</p>'}<div class="formgrid"><div class="field"><label>Conselho</label><select class="in" ${d}><option ${!cons[1]?'selected':''}>—</option>${['CRBM','CRF','CRM','COREN','CRBio'].map(c=>`<option ${cons[1]&&cons[1].startsWith(c)?'selected':''}>${c}</option>`).join('')}</select></div><div class="field"><label>Número</label><input class="in" value="${cons[3]||''}" ${d} placeholder="12345"></div><div class="field"><label>Região / UF</label><input class="in" value="${cons[2]||(cons[1]?cons[1].split('-')[1]||'':'')}" ${d} placeholder="Ex.: 1ª ou CE"></div><div class="field"><label>Assinatura digital</label><select class="in" ${d}><option ${assina?'selected':''}>ICP-Brasil em nuvem</option><option>Certificado A1 (arquivo)</option><option>Assinatura avançada do DeoClinic</option><option ${assina?'':'selected'}>Não assina</option></select></div><div class="field"><label>Validade do certificado</label><input class="in" type="date" value="${assina?'2027-03-15':''}" ${d}></div><div class="field"><label>Imagem da assinatura ${info('Aparece no laudo impresso junto da assinatura eletrônica.')}</label><button class="btn sm ghost" ${d} onclick="toast('Imagem da assinatura enviada (PNG com fundo transparente)')">Enviar imagem</button></div></div>
<h4 style="margin-top:12px">Dados de acesso ${info('A senha é criada pela própria pessoa pelo e-mail de ativação; o operador nunca vê nem define senha.')}</h4><div class="formgrid"><div class="field"><label>Login</label><input class="in" value="${u.email||'(o e-mail acima)'}" disabled></div><div class="field"><label>Segundo fator ${info('Padrão vem do perfil (opcional nos 9 perfis padrão); o administrador ajusta por usuário.')}</label><select class="in" ${d}><option>Opcional (padrão do perfil)</option><option>Obrigatório · aplicativo</option><option>Obrigatório · SMS</option></select></div><div class="field"><label>Situação</label><div style="padding-top:6px"><span class="badge ${u.sit==='Ativo'?'ok':u.sit==='Inativo'?'neutral':'warn'}">${u.sit||'Novo'}</span>${u.n?' <span class="tl">· último acesso hoje 08:41 · Chrome · Fortaleza</span>':''}</div></div></div>${novo||ver?'':`<div class="row" style="gap:6px;margin-top:8px"><button class="btn sm ghost" onclick="toast('E-mail de ativação reenviado para ${u.email}')">Reenviar ativação</button><button class="btn sm ghost" onclick="toast('No próximo acesso a pessoa terá que criar outra senha')">Exigir troca de senha</button><button class="btn sm ghost" onclick="toast('Sessões encerradas em todos os aparelhos','warn')">Encerrar sessões</button></div>`}
<p class="tl" style="margin-top:10px">Cada campo tem o "i" com a finalidade (LGPD). Campos opcionais que não cabem aqui (RG, cargo, CBO e CNS para o TISS, admissão, contato de emergência) ficam em "Mais dados", preenchidos pela própria pessoa no primeiro acesso.</p></div><div class="mf"><button class="btn ghost" onclick="closeModal()">${ver?'Fechar':'Cancelar'}</button>${ver?`<button class="btn sec" onclick="usForm(${i})">Editar</button>`:`<button class="btn" onclick="closeModal();retorno('ok','${novo?'Usuário cadastrado':'Usuário salvo'}','${novo?'E-mail de ativação enviado: a pessoa cria a própria senha e, se exigido, o segundo fator.':'Alterações registradas na auditoria com antes e depois; exceções de permissão valem no próximo acesso.'}')">${novo?'Cadastrar':'Salvar'}</button>`}</div>`,'wide')}
function usCep(){const cep=(document.getElementById('usCep').value||'').replace(/\D/g,'');if(cep.length<8){toast('Digite o CEP completo','warn');return}document.getElementById('usRua').value='Rua Tibúrcio Cavalcante';document.getElementById('usBairro').value='Aldeota';document.getElementById('usCidade').value='Fortaleza';document.getElementById('usUf').value='CE';toast('Endereço preenchido pelo CEP (ViaCEP); confira o número')}
/* 123: link de cadastro com perfil pré-selecionado, enviado por mensagem; a pessoa preenche no celular e tira a foto na hora */
let US_LINK=null;
function usLink(){US_LINK=null;openModal(`${mh('Gerar link de cadastro')}<div class="mb">${deoFala(92,{admin:'Gere o link e mande pelo WhatsApp: a pessoa preenche no celular e tira a foto na hora. Você só aprova. Delegar nunca foi tão bonito.',gestor:'Cada usuário herda o perfil e guarda só as exceções. É a única herança que não dá briga.',todos:'Senha quem cria é a pessoa. Foto quem tira é a pessoa. Eu só guardo, pequenininho, sem pesar o banco.'})}<div class="formgrid"><div class="field"><label>Perfil do novo usuário <span class="req">*</span> ${info('Já vai escolhido: a pessoa não muda o perfil, só preenche os próprios dados.')}</label><select class="in" id="ulPerfil">${PERFIS.map(p=>`<option value="${p[0]}">${p[1]}</option>`).join('')}</select></div><div class="field"><label>Unidade padrão</label><select class="in" id="ulUnid"><option>Unidade 10 · Central</option><option>Posto 12 · Messejana</option><option>Posto 14 · Aldeota</option></select></div><div class="field"><label>Validade do link</label><select class="in" id="ulVal"><option>7 dias (padrão)</option><option>24 horas</option><option>3 dias</option></select></div><div class="field"><label>Nome de quem vai se cadastrar ${info('Opcional; só para a mensagem ficar com o nome.')}</label><input class="in" id="ulNome" placeholder="Ex.: Juliana"></div></div><div id="ulRes"></div><div class="alert info" style="margin-top:10px"><span>A pessoa abre o link no celular, preenche nome, CPF, e-mail e telefone, <b>tira a foto na hora pela câmera</b>, cria a senha e o segundo fator se exigido. O link vale uma vez; a conta só ativa depois da sua aprovação. Geração, uso e aprovação ficam na auditoria.</span></div></div><div class="mf"><button class="btn ghost" onclick="closeModal()">Fechar</button><button class="btn" id="ulGerar" onclick="usLinkGerar()">Gerar link</button></div>`)}
function usLinkGerar(){const cod=Math.random().toString(36).slice(2,6).toUpperCase()+Math.random().toString(36).slice(2,4).toUpperCase();US_LINK='deoclinic.app/c/'+cod;const p=document.getElementById('ulPerfil'),perfil=p.options[p.selectedIndex].text,nome=(document.getElementById('ulNome').value||'').trim(),val=document.getElementById('ulVal').value.split(' (')[0];
 const msg=`Olá${nome?' '+nome:''}! Aqui é do DeoClinic. Seu cadastro como ${perfil} já está pronto para você terminar pelo celular: ${US_LINK} (vale ${val}). Preencha seus dados e tire a foto na hora. Qualquer dúvida, é só responder aqui.`;
 document.getElementById('ulRes').innerHTML=`<div class="card at-card" style="margin-top:10px;padding:12px 14px"><div class="row" style="gap:8px;align-items:center"><span class="mono" style="font-size:16px;font-weight:700;color:var(--fg-strong)">${US_LINK}</span><span class="badge ok">vale ${val} · uma vez</span><button class="btn sm sec" onclick="navigator.clipboard&&navigator.clipboard.writeText('${US_LINK}');toast('Link copiado')">Copiar</button></div><p class="tl" style="margin:8px 0 6px">Mensagem pronta (edite se quiser):</p><textarea class="in" id="ulMsg" rows="4" style="height:auto">${msg}</textarea><div class="row" style="gap:6px;margin-top:8px"><button class="btn sm" onclick="toast('Enviado por WhatsApp com o link do cadastro')"><span class="wa-ic"><i class="fa-brands fa-whatsapp"></i></span> WhatsApp</button><button class="btn sm sec" onclick="toast('Enviado por SMS')">SMS</button><button class="btn sm sec" onclick="toast('Enviado por e-mail')">E-mail</button></div></div>`;const g=document.getElementById('ulGerar');if(g){g.textContent='Gerar outro link';g.className='btn sec'}toast('Link gerado; vale '+val+' e uma vez')}

/* ======================= 124 e 125. Perfis: quadros sem sobreposição e Dr. Deo ======================= */
const PF_FALA={admin:'Administrador: todas as chaves, menos a da assinatura. Ter o molho inteiro e não abrir a última porta é o preço de mandar.',gestor:'Gestor de posto vê o caixa do posto e a fila do posto. O resto é com a matriz, e a matriz sabe disso.',recepcao:'Recepção não vê a área técnica. É proteção: ninguém merece ver uma centrífuga de perto antes do café.',coletador:'Coletador: o único perfil que trabalha de pé, no app e, às vezes, na casa do paciente com cachorro.',tecnico:'Técnico vê bancada, controle e soroteca. Laudo assinado, só de longe, igual vitrine de padaria.',dr:'Dr. é o único que libera e assina. Com conselho, número e UF, e a responsabilidade que vem junto, de brinde.',financeiro:'Financeiro vê tudo que tem cifrão. Inclusive o que não devia ter.',convenios:'Convênios: o perfil que fala TISS fluente e discute glosa como quem discute futebol.',qualidade:'Perfil Qualidade: a pessoa que lê o procedimento até o fim. Toda clínica precisa de uma.',medico:'Médico: prontuário, prescrição e atestado, assinados. Vê o resultado do laboratório e o laudo da imagem do próprio paciente, sem papel.',enfermagem:'Enfermagem: triagem, sinais vitais e leitos. Prescreve? Não. Salva o dia? Todo dia.',imagem:'Médico de imagem: realiza, lauda e assina. O gel acaba, o laudo não pode atrasar.',estoque:'Estoque: entrada, saída, lote e validade. O kit de cada procedimento baixa sozinho, mas quem confere é você.',faturamento:'Faturamento: guia, lote e glosa. Fala TUSS como quem fala português.'};
const PF_DESC={admin:'Configura o laboratório, perfis e usuários; vê tudo, mas não assina laudo.',gestor:'Cuida do posto: fila, caixa, transporte e licença; vê os caixas do posto.',recepcao:'Atende, orça, recebe e entrega; não vê a área técnica.',coletador:'Coleta no laboratório e em casa pelo app; registra tubo a tubo.',tecnico:'Recebe amostras, roda a bancada, digita e cuida do controle de qualidade.',dr:'Confere, libera e assina resultados; recebe críticos e urgências.',financeiro:'Contas, faturamento, conciliação dos caixas e indicadores.',convenios:'Guias TISS, lotes, glosas e recursos dos convênios.',qualidade:'Não conformidades, documentos, auditorias e indicadores ISO 9001 e PALC.',medico:'Agenda própria, prontuário, prescrição, atestado e pedidos; vê resultados e laudos dos seus pacientes.',enfermagem:'Triagem com sinais vitais e risco, fila, leitos e checagem; baixa de insumos da sala.',imagem:'Realiza e lauda ultrassom e outros exames de imagem; assina com conselho.',estoque:'Itens, entradas, saídas, lotes, validades, inventário e pedidos de compra; kits por procedimento.',faturamento:'Guias, autorizações, lotes TISS, glosas e recursos; TUSS e tabelas dos convênios.'};
VIEWS.perfis=()=>`${pageHead('Cadastros','Perfis e permissões','Um modelo só para a plataforma inteira: cada perfil guarda permissões por ação e o escopo de unidade, checados no servidor; o usuário herda e guarda só exceções. Dados de exemplo.',`${rulesBtn('Perfis e permissões')}<button class="btn" onclick="pfForm()" ${tipAttr('Criar perfil','Só o nome é obrigatório; descrição e avatar opcionais; permissões começam desligadas.')}>${I.plus} Criar perfil</button>`)}
<div class="filters"><div class="inwrap" style="flex:1 1 220px">${LUPA}<input class="in" placeholder="Nome ou situação" oninput="document.querySelectorAll('.pgrid .pcard2').forEach(c=>c.hidden=!semAc(c.textContent).includes(semAc(this.value)))"></div><span class="tl">${PERFIS.length} perfis padrão da plataforma, editáveis e copiáveis · permissões por ação e escopo de unidade · clique no quadro</span></div>
<div class="pgrid">${PERFIS.map(([id,n])=>{const ativos=USUARIOS.filter(u=>u.perfil===id&&u.sit==='Ativo').length;return `<div class="pcard2" onclick="pfForm('${id}',true)"><div class="ph"><span class="avatar">${n.slice(0,2).toUpperCase()}</span><div class="nm"><b ${tipAttr(n,(PF_DESC[id]||'')+' Clique no quadro para ver as permissões.')}>${n}</b><small>${(PERM_PERFIL[id]||[]).length} módulos · ${escopoNome(PERM_ESCOPO[id]).toLowerCase()} · ${ativos} ${ativos===1?'usuário':'usuários'}${id===PERFIL?' · <span style="color:var(--accent);font-weight:700">seu perfil</span>':''}</small></div><span class="badge ok">Ativo</span></div><div class="pd">${PF_DESC[id]||'Perfil criado pela clínica.'}</div><div class="pf"><span class="tl">${id==='dr'?'libera e assina':['medico','imagem'].includes(id)?'assina prontuário e laudo':id==='admin'?'tudo, menos liberar':'segundo fator opcional'}</span>${acoesCad(true,`pfForm('${id}')`,`pfForm('${id}',true)`,`toast('${id==='admin'?'Não dá para desativar o último perfil com Gestão de Perfis':'Desativar bloqueia na hora os usuários ligados; os '+USUARIOS.filter(u=>u.perfil===id).length+' usuários precisam de outro perfil'}','warn')`)}</div></div>`}).join('')}</div>
${piada(43,{admin:'Administrador faz tudo, menos assinar laudo. É o único cargo em que ter todas as chaves não abre a última porta.',dr:'Dr. é o único perfil que libera e assina. Poder, com conselho, número e UF.',qualidade:'Permissão de ver resultados sensíveis é permissão própria. Curiosidade não é perfil.',todos:'Perfil é modelo, exceção é no usuário. Como calça: o tamanho é padrão, a barra é sua.'})}`;
/* Na janela de cada perfil, o Dr. Deo fala do perfil aberto (anotação 125) */
{const _pf=pfForm;pfForm=function(id,ver){_pf(id,ver);if(!id||!BRINCA)return;const mb=document.querySelector('#modal .mb');if(mb&&PF_FALA[id])mb.insertAdjacentHTML('afterbegin',`<div class="deo">${FIG('ok','pq')}<div class="fala"><b>Dr. Deo diz:</b> ${PF_FALA[id]}<span class="fun">brincadeira 93</span></div></div>`)}}

/* ======================= 140 e 141. Estabelecimentos: pacientes e exames por laboratório, postos à escolha, régua explicada ======================= */
const ES_SERIES={'DeoClinic · Central':{cor:'var(--accent)',pac:[3610,3700,3820,3850,3760,3902],ex:[13900,14260,14710,14820,14480,15030]},'Posto 12 · Messejana':{cor:'#2979FF',pac:[820,860,880,910,870,902],ex:[2870,3010,3080,3190,3040,3160]},'Posto 14 · Aldeota':{cor:'#8E24AA',pac:[1140,1180,1230,1260,1210,1284],ex:[4220,4370,4550,4660,4480,4750]},'Vida Clínica (Sobral)':{cor:'#17B86E',pac:[1210,1290,1380,1420,1460,1508],ex:[4360,4640,4970,5110,5260,5430]},'Lab Bem Estar (Juazeiro)':{cor:'#F28C28',pac:[0,0,0,120,340,610],ex:[0,0,0,410,1190,2140]}};
const ES_MESES=['mai','jun','jul','ago','set','out'];
let ES_SEL=new Set(['DeoClinic · Central','Vida Clínica (Sobral)']);
function esSel(n){if(n==='DeoClinic · Central')return;if(ES_SEL.has(n)){if(ES_SEL.size>1)ES_SEL.delete(n)}else ES_SEL.add(n);reView()}
/* Linhas com várias séries; cada ponto mostra o valor real do mês ao passar o mouse e abre a lista ao clicar */
function svgLinhas(labels,series,o={}){const W=480,H=160,L=42,R=12,T=14,B=24;const n=labels.length;const todos=series.flatMap(s=>s.v);let lo=0,hi=Math.max(...todos,1);hi+= (hi-lo)*.12;const x=i=>L+i*(W-L-R)/(n-1),y=v=>T+(H-T-B)*(1-(v-lo)/(hi-lo));const f=v=>v.toLocaleString('pt-BR');
 return `<svg class="gsvg" viewBox="0 0 ${W} ${H}" role="img" aria-label="${o.aria||'Gráfico'}">${[0,.5,1].map(k=>`<line x1="${L}" x2="${W-R}" y1="${(T+(H-T-B)*k).toFixed(1)}" y2="${(T+(H-T-B)*k).toFixed(1)}" stroke="var(--border)"/>`).join('')}${series.map(s=>`<polyline fill="none" stroke="${s.cor}" stroke-width="2.5" stroke-linejoin="round" points="${s.v.map((v,i)=>`${x(i).toFixed(1)},${y(v).toFixed(1)}`).join(' ')}"/>`).join('')}${series.map(s=>s.v.map((v,i)=>`<circle cx="${x(i).toFixed(1)}" cy="${y(v).toFixed(1)}" r="5" fill="${s.cor}" stroke="var(--surface)" stroke-width="1.5" style="cursor:pointer" onmouseenter="esTip(event,'${esc(s.n)} · ${labels[i]}/26: ${f(v)} ${o.unid||''}')" onmouseleave="esTipOff()" onclick="listaDrawer('${esc(s.n)} · ${labels[i]}/2026',['<b>${f(v)} ${o.unid||''}</b><small>no mês</small>','<b>${f(Math.round(v/22))} por dia útil</b><small>média de 22 dias</small>'])"><title>${esc(s.n)} · ${labels[i]}: ${f(v)}</title></circle>`).join('')).join('')}${labels.map((l,i)=>`<text x="${x(i).toFixed(1)}" y="${H-8}" text-anchor="middle" font-size="10" fill="var(--fg2)">${l}</text>`).join('')}<text x="${L-4}" y="${T+4}" text-anchor="end" font-size="9" fill="var(--fg2)">${f(Math.round(hi/1.12))}</text><text x="${L-4}" y="${H-B+3}" text-anchor="end" font-size="9" fill="var(--fg2)">0</text></svg>`}
function esTip(e,txt){let t=document.getElementById('es-tip');if(!t){t=document.createElement('div');t.id='es-tip';document.body.appendChild(t)}t.textContent=txt;t.style.display='block';const b=e.target.getBoundingClientRect();t.style.left=Math.min(innerWidth-t.offsetWidth-8,Math.max(8,b.left+b.width/2-t.offsetWidth/2))+'px';t.style.top=(b.top-t.offsetHeight-8)+'px'}
function esTipOff(){const t=document.getElementById('es-tip');if(t)t.style.display='none'}
function esGraficos(){const sel=Object.keys(ES_SERIES).filter(n=>ES_SEL.has(n));const chips=`<div class="es-chips"><span class="tl">Comparar a central com:</span>${Object.keys(ES_SERIES).filter(n=>n!=='DeoClinic · Central').map(n=>`<button class="chip ${ES_SEL.has(n)?'on':''}" onclick="esSel('${n}')" ${tipAttr(n,'Liga ou desliga esta unidade nos dois gráficos. Pode escolher mais de uma.')}><i style="background:${ES_SERIES[n].cor}"></i>${n.split(' (')[0].replace(' · ',' ')}</button>`).join('')}</div>`;
 const leg=`<div class="es-leg">${sel.map(n=>`<span><i style="background:${ES_SERIES[n].cor}"></i>${n}</span>`).join('')}</div>`;
 return `<div class="card ill at-card">${ILL.grafico}<h3>Pacientes atendidos por cliente · 6 meses ${info('Número de pacientes (atendimentos), por mês, da central e das unidades que você escolher. Passe o mouse na bolinha para o valor do mês; clique para abrir.')}</h3>${chips}${svgLinhas(ES_MESES,sel.map(n=>({n,cor:ES_SERIES[n].cor,v:ES_SERIES[n].pac})),{unid:'pacientes',aria:'Pacientes por mês'})}${leg}</div>
<div class="card ill at-card">${ILL.grafico}<h3>Exames realizados por cliente · 6 meses ${info('Número de exames (um paciente faz vários), por mês, das mesmas unidades escolhidas ao lado. Passe o mouse na bolinha para o valor do mês; clique para abrir.')}</h3><p class="tl" style="margin-bottom:6px">Mesma escolha de unidades do gráfico ao lado · média de ${(sel.reduce((s,n)=>s+ES_SERIES[n].ex[5],0)/Math.max(1,sel.reduce((s,n)=>s+ES_SERIES[n].pac[5],0))).toFixed(1).replace('.',',')} exames por paciente em outubro</p>${svgLinhas(ES_MESES,sel.map(n=>({n,cor:ES_SERIES[n].cor,v:ES_SERIES[n].ex})),{unid:'exames',aria:'Exames por mês'})}${leg}</div>`}
const REGUA_HTML=`<span class="regua-lic"><span class="badge warn" ${tipAttr('Aviso · 15 dias','Mensalidade atrasada há 15 dias: aviso ao responsável por e-mail e WhatsApp; o sistema continua normal.')}>15 d · aviso</span><span class="badge err" style="background:#FBEFE3;color:#C96F1B" ${tipAttr('Restrição · 30 dias','Atraso de 30 dias: o cliente não abre atendimentos novos; o que já está em andamento termina e os laudos saem.')}>30 d · restrição</span><span class="badge err" ${tipAttr('Bloqueio · 60 dias','Atraso de 60 dias: acesso bloqueado até o pagamento; os dados ficam guardados e nada é apagado.')}>60 d · bloqueio</span></span>`;
{const _es=VIEWS.estabelecimentos;VIEWS.estabelecimentos=()=>{let h=_es();const a=h.indexOf('<div class="card ill at-card">'+ILL.grafico),b=h.indexOf('<div class="card ill at-card">'+ILL.pizza);if(a>=0&&b>a)h=h.slice(0,a)+esGraficos()+h.slice(b);
 h=h.replace('<div class="card ill at-card">'+ILL.cofre,'<div class="card ill at-card span2">'+ILL.cofre).replace('<th>Régua</th>',`<th>Régua de inadimplência ${info('O que acontece quando a mensalidade atrasa: aviso, depois restrição, depois bloqueio. Prazos configuráveis por cliente.')}</th>`).replace(/<td data-l="Régua">[^<]*<\/td>/g,`<td data-l="Régua">${REGUA_HTML}</td>`);
 return h}}

