function inBlocos(){const adm=PERFIL==='admin';const st=s=>`<span class="badge ${s==='Ativo'?'ok':s==='Com falha'?'err':s==='Em testes'?'info':'neutral'}">${s==='Ativo'?'conectado':s.toLowerCase()}</span>`;
 return `<div class="in-blocos">${IN_BLOCOS.map(([n,sub,idx,link,txt])=>{if(!idx){return `<div class="in-bloco"><div class="ih"><b>${n}</b>${st('Ativo')}</div><div class="tl">${sub}</div><div class="troca"><span>troca</span><span>${txt}</span></div><div class="meta"><span>último resultado: hoje 08:58</span><span>3 aparelhos online · 1 calado</span></div><div class="ia"><button class="btn sm sec" onclick="location.hash='${link}'">Abrir Aparelhos</button><button class="btn sm ghost" onclick="apTestar('DxH 800')">Testar</button></div></div>`}
  const xs=idx.map(i=>IN_PARC[i]).filter(Boolean);const x=xs[0];const sit=xs.some(z=>z.s==='Com falha')?'Com falha':x.s;return `<div class="in-bloco"><div class="ih"><b>${n}</b>${st(sit)}</div><div class="tl">${sub}</div><div class="troca"><span>entra</span><span>${x.troca[0]}</span><span>sai</span><span>${x.troca[1]}</span></div><div class="meta"><span>chave <span class="mono">${xs.map(z=>z.chave).join(' · ')}</span></span><span>último sincronismo: ${xs.map(z=>z.sync).join(' · ')}</span></div><div class="ia">${xs.map(z=>`<button class="btn sm sec" onclick="inDetalhe(${IN_PARC.indexOf(z)})">${xs.length>1?z.p.split(' ')[0]+' · ':''}Detalhes</button>`).join('')}<button class="btn sm ghost" onclick="toast('Ambiente simulado: mensagem de teste enviada a ${esc(x.p)} e resposta recebida em 0,8 s')">Testar</button>${adm?'':'<span class="tl" style="align-self:center">só leitura</span>'}</div></div>`}).join('')}</div>${adm?'':'<p class="tl" style="margin:-6px 0 12px">Detalhes de integração são editados só pelo Administrador.</p>'}`}
{const _in=VIEWS.integracoes;VIEWS.integracoes=()=>{let h=_in();if(IN_ABA==='parceiros'){h=h.replace('<div class="tablewrap">','<h4 style="margin:4px 0 8px">O que o DeoClinic troca com cada sistema '+info('Um bloco por integração: o que entra, o que sai, chave, último sincronismo e teste. Aparelhos têm tela própria. Detalhes editáveis só pelo Administrador.')+'</h4>'+inBlocos()+deoFala(95,{admin:'Clínicas, Fidelidade, App, Estoque, Pardini, DB e os aparelhos: sete conversas ao mesmo tempo e eu sem perder o fio. Tente isso num grupo de família.',tecnico:'Cada exame que você roda dá baixa no reagente lá no Estoque. O frasco vazio na bancada agora é oficial.',financeiro:'Fidelidade manda o assinante, o DeoClinic manda o exame realizado, e o cashback nasce sem planilha. Milagre contábil.',todos:'Integração boa é a que ninguém percebe. Integração ruim vira grupo de WhatsApp às 23h.'})+'<h4 style="margin:4px 0 8px">Parceiros e chaves</h4><div class="tablewrap">')}
 return h}}
function inDetalhe(i){const x=IN_PARC[i];const adm=PERFIL==='admin';const campo=(l,v,tip)=>adm?`<div class="field"><label>${l}${tip?' '+info(tip):''}</label><input class="in" value="${esc(v)}"></div>`:`<div class="field"><label>${l}</label><div style="font-size:14px">${esc(v)}</div></div>`;
 openDrawer(x.p,`${adm?'':'<div class="alert info"><span>Só leitura: só o Administrador altera integrações.</span></div>'}${kvs([['Tipo',x.t],['Padrão',x.pa],['Situação',`<span class="badge ${x.s==='Ativo'?'ok':x.s==='Com falha'?'err':x.s==='Em testes'?'info':'neutral'}">${x.s}</span>`],['Chamadas (24 h)',x.n+(x.f!=='0'&&x.f!=='—'?' · <span class="prazo-err">'+x.f+' falhas</span>':'')],x.troca?['Entra no DeoClinic',x.troca[0]]:null,x.troca?['Sai do DeoClinic',x.troca[1]]:null,['Eventos',x.ev],x.sync?['Último sincronismo',x.sync]:null,x.chave?['Chave',`<span class="mono">${x.chave}</span>`]:null])}<h4 style="margin-top:10px">Configuração ${info('Chave mostrada uma vez; credenciais cifradas; toda mudança vai para a auditoria com antes e depois.')}</h4><div class="formgrid">${campo('Endereço de callback',x.c)}${campo('Permissões por recurso',x.perm)}${campo('Limite de chamadas',x.lim)}${campo('Versão da API','v1')}</div>${x.t.startsWith('App ·')?'<div class="alert info"><span><b>Um app para os dois perfis:</b> coletador e Dr. entram no mesmo aplicativo; o perfil do usuário decide a área que abre. Sem um segundo app para manter.</span></div>':''}${x.p==='Estoque'?'<div class="alert info"><span><b>Consumo por teste:</b> cada exame tem, no cadastro, quais reagentes e insumos gasta; ao liberar o resultado o DeoClinic manda a baixa ao Estoque e recebe de volta saldo e validade para avisar a bancada antes de faltar.</span></div>':''}<div class="row" style="margin-top:12px;gap:6px">${adm?`<button class="btn" onclick="toast('Integração salva; antes e depois na auditoria')">Salvar</button><button class="btn sec" onclick="toast('Chave rotacionada; a antiga vale por 24 h')">Nova chave</button><button class="btn ghost" onclick="toast('Ambiente simulado: mensagem de teste enviada e recebida')">Testar</button><button class="btn ghost" onclick="modalOk('Desligar integração?','<p>Mensagens param de sair e de entrar; a fila guarda as pendentes.</p>','Desligar','toast(\\'Integração desligada; registrado\\',\\'warn\\')','danger')">Desligar</button>`:''}<button class="btn ghost" onclick="closeDrawer();IN_ABA='monitor';reView()">Ver mensagens</button></div>`)}
